function b2_flake(x, y, r, a0) { var d = ''; for (var i = 0; i < 6; i++) { var a = a0 + i * Math.PI / 3, c = Math.cos(a), s = Math.sin(a); d += seg(x, y, x + c * r, y + s * r); [[0.5, 0.32], [0.76, 0.2]].forEach(function (f) { var bx = x + c * r * f[0], by = y + s * r * f[0], l = r * f[1]; [0.8, -0.8].forEach(function (sg) { var a2 = a + sg; d += seg(bx, by, bx + Math.cos(a2) * l, by + Math.sin(a2) * l); }); }); } return d; }
function b2_cloud(x, y, s) { return ell(x, y, 70 * s, 16 * s) + circ(x - 22 * s, y - 10 * s, 22 * s) + circ(x + 14 * s, y - 16 * s, 28 * s) + circ(x + 42 * s, y - 4 * s, 16 * s); }
// Tapered limb along a quadratic curve
function b2_limb(p0, p1, p2, w0, w1, N) { N = N || 14; var L = [], R = []; for (var i = 0; i <= N; i++) { var t = i / N, u = 1 - t, x = u * u * p0[0] + 2 * u * t * p1[0] + t * t * p2[0], y = u * u * p0[1] + 2 * u * t * p1[1] + t * t * p2[1], dx = 2 * u * (p1[0] - p0[0]) + 2 * t * (p2[0] - p1[0]), dy = 2 * u * (p1[1] - p0[1]) + 2 * t * (p2[1] - p1[1]), m = Math.sqrt(dx * dx + dy * dy) || 1, w = lerp(w0, w1, t) / 2; L.push([x - dy / m * w, y + dx / m * w]); R.unshift([x + dy / m * w, y - dx / m * w]); } return b2_polyA(L.concat(R)); }
function b2_qpt(p0, p1, p2, t) { var u = 1 - t; return [u * u * p0[0] + 2 * u * t * p1[0] + t * t * p2[0], u * u * p0[1] + 2 * u * t * p1[1] + t * t * p2[1]]; }
// Maple leaf (5 lobes) from stem base, pointing along ang (deg)
var B2_MAPLE = [[0, 0], [0.1, -0.12], [0.05, -0.45], [0.2, -0.38], [0.45, -0.6], [0.45, -0.35], [0.7, -0.4], [0.55, -0.18], [1, 0], [0.55, 0.18], [0.7, 0.4], [0.45, 0.35], [0.45, 0.6], [0.2, 0.38], [0.05, 0.45], [0.1, 0.12]];
function b2_maple(x, y, s, ang) { return b2_polyA(rotp(B2_MAPLE.map(function (p) { return [p[0] * s, p[1] * s]; }), x, y, ang)); }
function b2_oak(x, y, s, ang) { var up = [], lo = [], N = 16; for (var i = 0; i <= N; i++) { var t = i / N, w = s * 0.3 * Math.sin(Math.PI * Math.min(1, t * 1.05)) * (0.72 + 0.28 * Math.abs(Math.cos(t * Math.PI * 3.5))); up.push([t * s, -w]); lo.unshift([t * s, w]); } return b2_polyA(rotp(up.concat(lo), x, y, ang)); }
function b2_leaf(x, y, len, w, ang) { var pts = [], i; for (i = 0; i <= 12; i++) { var t = i / 12; pts.push([t * len, w * Math.sin(Math.PI * t) * (1 - 0.35 * t)]); } for (i = 11; i > 0; i--) { var u = i / 12; pts.push([u * len, -w * 0.7 * Math.sin(Math.PI * u) * (1 - 0.35 * u)]); } return b2_polyA(rotp(pts, x, y, ang)); }
