function b2_cup(x, y, s, tilt) { var o = [[-0.5, -0.55], [-0.47, -1.05], [-0.25, -0.8], [0, -1.22], [0.25, -0.8], [0.47, -1.05], [0.5, -0.55]]; for (var i = 1; i < 9; i++) { var a = i / 9 * Math.PI; o.push([0.5 * Math.cos(a), -0.55 + 0.55 * Math.sin(a)]); } var hi = [[-0.17, -0.3], [0, -1.12], [0.17, -0.3], [0, -0.12]]; function sc(p) { return p.map(function (q) { return [q[0] * s, q[1] * s]; }); } return {cup: poly(rotp(sc(o), x, y, tilt)), hi: poly(rotp(sc(hi), x, y, tilt))}; }
