  groups.forEach(function (g) { for (var i = 0; i < g[1]; i++) { var x = W * g[0] + (i - g[1] / 2) * (ph ? 16 : 22) + rnd() * 8, h = (ph ? 40 : 55) + rnd() * (ph ? 30 : 45), p = b2_pine(x, b2_y(b2b, w2, x) + 6, h, h * 0.5, 4); pt += p.d; psn += p.snow; } });
  var s = ph ? 0.95 : 1.15, cx = W * (ph ? 0.6 : 0.73), cy = b2_y(b2b, w2, cx) + 14 * s;
  var walls = rect(cx - 42 * s, cy - 36 * s, 84 * s, 36 * s) + rect(cx + 18 * s, cy - 76 * s, 11 * s, 30 * s);
  var roof = poly([[cx - 54 * s, cy - 34 * s], [cx, cy - 72 * s], [cx + 54 * s, cy - 34 * s], [cx + 50 * s, cy - 30 * s], [cx - 50 * s, cy - 30 * s]]) + ell(cx + 23.5 * s, cy - 76 * s, 8 * s, 3.5 * s);
  var under = poly([[cx - 48 * s, cy - 31 * s], [cx + 48 * s, cy - 31 * s], [cx + 44 * s, cy - 27 * s], [cx - 44 * s, cy - 27 * s]]) + rrect(cx - 8 * s, cy - 24 * s, 16 * s, 24 * s, 2);
