  var sx0 = cx + 23.5 * s, sy0 = cy - 82 * s, sm = 'M' + PT(sx0, sy0) + ' C' + PT(sx0 - 10, sy0 - 25) + ' ' + PT(sx0 + 22, sy0 - 40) + ' ' + PT(sx0 + 10, sy0 - 65) + ' S' + PT(sx0 + 40, sy0 - 100) + ' ' + PT(sx0 + 34, sy0 - 125) + ' ';
  if (ANIM) ANIM.smoke = {x: sx0, y: sy0, c: dk ? '#C8D4F0' : '#96A8C0', a: dk ? 0.35 : 0.45};
