  add(L, k[3], circ(x - s * 0.3, y - s * 1.8, s * 0.5) + circ(x - s * 0.75, y - s * 1.35, s * 0.3), cols[3]);
  var f = '';
  for (var i = 0; i < 6; i++) { var a = rnd() * 6.28, rr = s * (0.35 + rnd() * 0.75); f += ell(x + Math.cos(a) * rr, y - s * 1.4 + Math.sin(a) * rr * 0.7, s * 0.14, s * 0.11); }
  add(L, k[4], f, cols[4]);
