function b4_blade(x, y, h, w, lean) { var L = [], R = [], N = 7; for (var i = 0; i <= N; i++) { var t = i / N, cx = x + lean * t * t, cy = y - h * t, ww = w * (1 - t) * 0.5 + 0.15; L.push([cx - ww, cy]); R.unshift([cx + ww, cy]); } return poly(L.concat(R)); }
