function b4_qpts(x0, y0, cx, cy, x1, y1, n) { var o = []; for (var i = 0; i <= n; i++) { var t = i / n; o.push([(1 - t) * (1 - t) * x0 + 2 * (1 - t) * t * cx + t * t * x1, (1 - t) * (1 - t) * y0 + 2 * (1 - t) * t * cy + t * t * y1]); } return o; }
function b4_stem(x0, y0, cx, cy, x1, y1, w0, w1) { var P = b4_qpts(x0, y0, cx, cy, x1, y1, 14), L = [], R = []; P.forEach(function (p, i) { var q = P[Math.min(P.length - 1, i + 1)], o = P[Math.max(0, i - 1)], dx = q[0] - o[0], dy = q[1] - o[1], l = Math.hypot(dx, dy) || 1, w = (w0 + (w1 - w0) * i / (P.length - 1)) / 2; L.push([p[0] - dy / l * w, p[1] + dx / l * w]); R.unshift([p[0] + dy / l * w, p[1] - dx / l * w]); }); return poly(L.concat(R)); }
