  for (i = 0; i < 4; i++) { var t4 = 0.2 + i * 0.16, px = cxAt(t4) + (rnd() - 0.5) * hw(t4) * 1.1, r = w * (0.025 + rnd() * 0.02); rock += gn_ell(px, y + 2 + t4 * hD, r * 1.3, r, rnd() * 40 - 20); }
