  spurs.forEach(function (s) { var tx = W * s[0], bb = bands[2 + Math.floor(rnd() * 3)], ty = cy(tx, bb.y, bb.t) + 4; trees += circ(tx, ty - 14, 12) + circ(tx + 10, ty - 20, 9) + circ(tx - 9, ty - 9, 8) + rect(tx - 1.5, ty - 6, 3, 8); blobs.push([tx, ty - 14, 12], [tx + 10, ty - 20, 9], [tx - 9, ty - 9, 8], [tx, ty - 1, 3]); });
  var hidden = function (x, yy) { return blobs.some(function (c) { return Math.hypot(x - c[0], yy - c[1]) < c[2] + 1.6; }) || (x > hx - 15.5 && x < hx + 15.5 && yy > hy - 15 && yy < hy + 1.5) || (yy <= hy - 12.6 && yy > hy - 33.5 && Math.abs(x - hx) < 23.5 * Math.min(1, (yy - (hy - 33.5)) / 19.5)); };
