// shared helpers
function m2_offset(pts, d) {
  var out = [], n = pts.length;
  function nrm(a, b) { var dx = b[0] - a[0], dy = b[1] - a[1], l = Math.hypot(dx, dy) || 1; return [-dy / l, dx / l]; }
  for (var i = 0; i < n; i++) {
    var n0 = i > 0 ? nrm(pts[i - 1], pts[i]) : null, n1 = i < n - 1 ? nrm(pts[i], pts[i + 1]) : null;
    if (!n0) n0 = n1; if (!n1) n1 = n0;
    var mx = n0[0] + n1[0], my = n0[1] + n1[1], ml = Math.hypot(mx, my) || 1; mx /= ml; my /= ml;
    var k = d / Math.max(0.3, mx * n0[0] + my * n0[1]);
    out.push([pts[i][0] + mx * k, pts[i][1] + my * k]);
  }
  return out;
}
function m2_len(pts) { var L = [0]; for (var i = 1; i < pts.length; i++) L.push(L[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1])); return L; }
