    'C': [7.2, A(4.6, 5, 4.4, 5, -40, -320, 22)],
    'D': [7.4, cat([[0, 0], [0, 10], [2.6, 10]], A(2.6, 5, 4.6, 5, 90, -90, 18), [[2.6, 0], [0, 0]])],
