    'J': [6, cat([[5.6, 0], [5.6, 7]], A(3.2, 7, 2.4, 3, 0, 180, 10))],
    'K': [6.8, [[0, 0], [0, 10]], [[6.2, 0], [0, 6.2]], [[2.2, 4.2], [6.6, 10]]],
    'L': [5.8, [[0, 0], [0, 10], [5.6, 10]]],
    'M': [8.6, [[0, 10], [0, 0], [4.2, 6.4], [8.4, 0], [8.4, 10]]],
