// Text as stroke path data
function m2_text(str, x, y, s, jit, rnd, track) {
  var k = s / 10, cx = x, d = '', tr = track === undefined ? 2.4 : track;
  for (var i = 0; i < str.length; i++) {
    var g = m2_FONT[str[i]]; if (!g) continue;
    for (var j = 1; j < g.length; j++) { var st = g[j], pts = []; for (var q = 0; q < st.length; q++) { var jx = jit && rnd ? (rnd() - 0.5) * jit : 0, jy = jit && rnd ? (rnd() - 0.5) * jit : 0; pts.push([cx + st[q][0] * k + jx, y + st[q][1] * k + jy]); } d += pline(pts); }
    cx += (g[0] + tr) * k;
  }
  return {d: d, w: cx - x - tr * k};
}
function m2_textW(str, s, track) { var k = s / 10, w = 0, tr = track === undefined ? 2.4 : track; for (var i = 0; i < str.length; i++) { var g = m2_FONT[str[i]]; if (g) w += (g[0] + tr) * k; } return w - tr * k; }
// The same strokes as point lists (for engines that draw the text over time)
function m2_textStrokes(str, x, y, s, track) {
  var k = s / 10, cx = x, out = [], tr = track === undefined ? 2.4 : track;
  for (var i = 0; i < str.length; i++) { var g = m2_FONT[str[i]]; if (!g) continue; for (var j = 1; j < g.length; j++) out.push(g[j].map(function (p) { return [cx + p[0] * k, y + p[1] * k]; })); cx += (g[0] + tr) * k; }
  return out;
}
// Code glyphs ({ } < > / and the cursor), centred on x,y with height s, as stroke path data
function m2_glyph(ch, x, y, s) {
  function P(px, py) { return PT(x + px * s, y + py * s); }
  if (ch === '{') return 'M' + P(0.22, -0.5) + ' Q' + P(0.04, -0.5) + ' ' + P(0.04, -0.32) + ' L' + P(0.04, -0.14) + ' Q' + P(0.04, 0) + ' ' + P(-0.14, 0) + ' Q' + P(0.04, 0) + ' ' + P(0.04, 0.14) + ' L' + P(0.04, 0.32) + ' Q' + P(0.04, 0.5) + ' ' + P(0.22, 0.5) + ' ';
  if (ch === '}') return 'M' + P(-0.22, -0.5) + ' Q' + P(-0.04, -0.5) + ' ' + P(-0.04, -0.32) + ' L' + P(-0.04, -0.14) + ' Q' + P(-0.04, 0) + ' ' + P(0.14, 0) + ' Q' + P(-0.04, 0) + ' ' + P(-0.04, 0.14) + ' L' + P(-0.04, 0.32) + ' Q' + P(-0.04, 0.5) + ' ' + P(-0.22, 0.5) + ' ';
  if (ch === '<') return 'M' + P(0.2, -0.34) + ' L' + P(-0.2, 0) + ' L' + P(0.2, 0.34) + ' ';
  if (ch === '>') return 'M' + P(-0.2, -0.34) + ' L' + P(0.2, 0) + ' L' + P(-0.2, 0.34) + ' ';
  if (ch === '/') return 'M' + P(0.14, -0.44) + ' L' + P(-0.14, 0.44) + ' ';
  if (ch === '</>') return m2_glyph('<', x - s * 0.42, y, s) + m2_glyph('/', x, y, s) + m2_glyph('>', x + s * 0.42, y, s);
  if (ch === '{}') return m2_glyph('{', x - s * 0.2, y, s) + m2_glyph('}', x + s * 0.2, y, s);
  return '';
}

// Kawaii face parts as path data
function m2_faceD(x, y, s, happy) { var e = s * 0.3, er = s * 0.075, o = {eyes: '', blush: ell(x - s * 0.5, y + s * 0.16, s * 0.15, s * 0.09) + ell(x + s * 0.5, y + s * 0.16, s * 0.15, s * 0.09), smile: 'M' + PT(x - s * 0.14, y + s * 0.12) + ' Q' + PT(x, y + s * 0.3) + ' ' + PT(x + s * 0.14, y + s * 0.12) + ' '};
  if (happy) o.eyes = 'M' + PT(x - e - er * 1.6, y) + ' Q' + PT(x - e, y - er * 2.4) + ' ' + PT(x - e + er * 1.6, y) + ' M' + PT(x + e - er * 1.6, y) + ' Q' + PT(x + e, y - er * 2.4) + ' ' + PT(x + e + er * 1.6, y) + ' ';
  else o.eyes = circ(x - e, y, er) + circ(x + e, y, er); return o; }

