  var sx0 = hx1, sy0 = hT + 22 * s, sx1 = W * (ph ? 0.44 : 0.34);
  var c0 = W * (ph ? 0.52 : 0.4), c1 = W * (ph ? 0.8 : 0.52), cT = H * (ph ? 0.875 : 0.735), dR = (c1 - c0) * 0.3, dCx = (c0 + c1) / 2 - (c1 - c0) * 0.04, dBy = cT - dR * 0.42;
